} from "../types";
import type { BibEntry } from "./bibliography";
import {
  loadMetaFromIdb,
  loadRoomAnalysisFromIdb,
  loadRubricResultFromIdb,
  saveMetaToIdb,
  saveRoomAnalysisToIdb,
  saveRubricResultToIdb,
} from "./idb";
import { readFileAsJson, writeFileAsJson } from "./lix";

const MIGRATION_KEY = "folio-editorial-artifacts-migrated";

export function canClaimLegacyEditorialArtifacts(
  folioIds: readonly string[],
  activeFolioId: string,
): boolean {
  return folioIds.length === 1 && folioIds[0] === activeFolioId;
}

function scopedPath(folioId: string, filename: string): string {
  return `/folios/${folioId}/${filename}`;
}

async function moveLegacyArray<T extends { folioId?: string }>(
  folioId: string,
  legacyPath: string,
  filename: string,
): Promise<void> {
  const targetPath = scopedPath(folioId, filename);
  const existing = await readFileAsJson<T[]>(targetPath);
  if (Array.isArray(existing) && existing.length > 0) return;
  const legacy = await readFileAsJson<T[]>(legacyPath);
  if (!Array.isArray(legacy) || legacy.length === 0) return;
  await writeFileAsJson(
    targetPath,
    legacy.map((entry) => ({ ...entry, folioId })),
  );
  await writeFileAsJson(legacyPath, []);
}

/**
 * Attach pre-folio editorial artifacts to exactly one existing folio.
 *
 * This runs once, before a writer creates or switches to another folio. It
 * intentionally moves rather than copies the old singleton records so a new
 * folio can never inherit the previous room by falling back to legacy paths.
 */
export async function migrateLegacyEditorialArtifacts(
  folioId: string,
  claimLegacy: boolean,
): Promise<void> {
  // With multiple possible owners, preserve old unscoped data without showing
  // it in any folio. A later recovery can ask where it belongs.
  if (!folioId || !claimLegacy) return;
  const migrated = await loadMetaFromIdb<string>(MIGRATION_KEY);
  if (migrated) return;

  await Promise.all([
    moveLegacyArray<PersonaFeedback>(
      folioId,
      "/persona-notes.json",
      "persona-notes.json",
    ),
    moveLegacyArray<PersonaReply>(
      folioId,
      "/persona-replies.json",
      "persona-replies.json",
    ),
    moveLegacyArray<Suggestion>(
      folioId,
      "/suggestions.json",
      "suggestions.json",
    ),
  ]);

  const [legacyRubric, legacyLixRubric, legacyAnalysis, criteria, history] =
    await Promise.all([
      loadRubricResultFromIdb(),
      readFileAsJson<RubricResult>("/rubric-result.json"),
      loadRoomAnalysisFromIdb(),
      loadMetaFromIdb<RubricCriterionSpec[]>("rubric-criteria"),
      loadMetaFromIdb<RubricHistoryEntry[]>("rubric-history"),
    ]);
  const rubric = legacyRubric ?? legacyLixRubric;
  if (rubric) {
    await saveRubricResultToIdb(
      { ...rubric, folioId } as RubricResult,
      folioId,
    );
    await writeFileAsJson(scopedPath(folioId, "rubric-result.json"), {
      ...rubric,
      folioId,
    });
    if (legacyLixRubric) {
      await writeFileAsJson("/rubric-result.json", null);
    }
  }
  if (legacyAnalysis) {
    await saveRoomAnalysisToIdb(
      { ...legacyAnalysis, folioId } as RoomAnalysis,
      folioId,
    );
  }
  if (Array.isArray(criteria) && criteria.length > 0) {
    await saveMetaToIdb(`rubric-criteria:${folioId}`, criteria);
  }
  if (Array.isArray(history) && history.length > 0) {
    await saveMetaToIdb(
      `rubric-history:${folioId}`,
      history.map((entry) => ({ ...entry, folioId })),
    );
  }

  const comments =
    (await readFileAsJson<Array<{ folioId?: string }>>(
      "/user-comments.json",
    )) ?? [];
  if (comments.length > 0) {
    await writeFileAsJson(
      "/user-comments.json",
      comments.map((comment) =>
        comment.folioId ? comment : { ...comment, folioId },
      ),
    );
  }

  const bibliography =
    (await readFileAsJson<BibEntry[]>("/bibliography.json")) ?? [];
  if (bibliography.length > 0) {
    await writeFileAsJson(
      "/bibliography.json",
      bibliography.map((entry) =>
        entry.folioId ? entry : { ...entry, folioId },
      ),
    );
  }

  await saveMetaToIdb(MIGRATION_KEY, folioId);
}
/**
 * Desktop shell bridge.
 *
 * The Electrobun desktop app loads the hosted web app in a native window at
 * `https://twyne.love/?platform=desktop&localAi=1&localPort=<port>`. This
 * module reads those URL params once so the rest of the web app can tell it is
 * running inside the desktop shell and discover the local MiniCPM5 LiteRT
 * endpoint that the desktop's Bun process exposes on loopback.
 *
 * On the plain web (no params) every getter is inert, so importing this is
 * safe and the local-AI surface stays hidden.
 */

interface DesktopContext {
  isDesktop: boolean;
  localAi: boolean;
  localPort: number | null;
}

let _ctx: DesktopContext | null = null;

function read(): DesktopContext {
  if (_ctx) return _ctx;
  if (typeof window === "undefined" || !window.location) {
    return { isDesktop: false, localAi: false, localPort: null };
  }
  const params = new URLSearchParams(window.location.search);
  const isDesktop = params.get("platform") === "desktop";
  const localAi =
    isDesktop &&
    (params.get("localAi") === "1" || params.get("localAi") === "true");
  const portRaw = params.get("localPort");
  const localPort =
    portRaw && /^\d+$/.test(portRaw) ? parseInt(portRaw, 10) : null;
  _ctx = { isDesktop, localAi, localPort };
  return _ctx;
}

export function isDesktopShell(): boolean {
  return read().isDesktop;
}

/**
 * True when the desktop shell explicitly advertised a local model endpoint.
 *
 * The desktop app only includes `localAi=1&localPort=<n>` after it has chosen
 * to launch the bundled LiteRT-LM server. Treat those params as the authoritative
 * capability signal so panels that normalize settings during first mount do
 * not miss the managed provider while PostHog flags are still loading.
 */
export function isDesktopLocalAiAvailable(): boolean {
  const ctx = read();
  return ctx.isDesktop && ctx.localAi && ctx.localPort !== null;
}

/** OpenAI-compatible base URL for the desktop's local LiteRT server, or null. */
export function localAiBaseUrl(): string | null {
  const ctx = read();
  if (!isDesktopLocalAiAvailable() || ctx.localPort === null) return null;
  return `http://127.0.0.1:${ctx.localPort}/v1`;
}

/** Default model id for the desktop local provider. */
export const LOCAL_MODEL_ID = "minicpm5-2b";

/** Stable provider id for the auto-registered local provider. */
export const LOCAL_PROVIDER_ID = "desktop-litert-local";

export function resetDesktopContextForTests(): void {
  _ctx = null;
}
export const EDITOR_VIEW_PREFERENCES_KEY = "twyne:editor:view:v1";
export interface EditorViewPreferences {
  zenMode: boolean;
  compositorOpen: boolean;
}
export const DEFAULT_EDITOR_VIEW_PREFERENCES: EditorViewPreferences = {
  zenMode: true,
  compositorOpen: false,
};

/** Device-local presentation only; never stores manuscript or account data. */
export function loadEditorViewPreferences(
  storage: Pick<Storage, "getItem">,
): EditorViewPreferences {
  try {
    const saved = JSON.parse(
      storage.getItem(EDITOR_VIEW_PREFERENCES_KEY) ?? "null",
    );
    return {
      zenMode: typeof saved?.zenMode === "boolean" ? saved.zenMode : true,
      compositorOpen:
        typeof saved?.compositorOpen === "boolean"
          ? saved.compositorOpen
          : false,
    };
  } catch {
    return { ...DEFAULT_EDITOR_VIEW_PREFERENCES };
  }
}

export function saveEditorViewPreferences(
  storage: Pick<Storage, "setItem">,
  preferences: EditorViewPreferences,
): void {
  try {
    storage.setItem(EDITOR_VIEW_PREFERENCES_KEY, JSON.stringify(preferences));
  } catch {
    // Tools stay available when private browsing or quota prevents persistence.
  }
}
