            )}
          </div>
          <div class={store.rightPanel === "rubric" ? "h-full" : "hidden"}>
            {store.activeFolioId && (
              <RubricPanel
                key={`rubric-${store.activeFolioId}`}
                brief={
                  store.modelBriefFolioId === store.activeFolioId
