import {
  component$,
  $,
  useSignal,
  useStore,
  useVisibleTask$,
} from "@qwik.dev/core";
import { useNavigate } from "@qwik.dev/router";
import type { DocumentHead } from "@qwik.dev/router";
import { AntiTabulaRasa } from "../../../components/onboarding/anti-tabula-rasa";
import { ConversationalInterview } from "../../../components/onboarding/conversational-interview";
import { AuthPanel } from "../../../components/auth/auth-panel";
import { useAuth } from "../../../utils/auth-context";
import type {
  DossierAttachment,
  DossierProbe,
  Folio,
  InterviewStyle,
  ProjectInterviewAnswers,
} from "../../../types";
import {
  buildImportedMaterialDocument,
  buildStarterDocument,
  clearStartingMaterial,
  createProjectBrief,
  briefTitleFromFolioName,
  loadStartingMaterial,
  loadProjectBriefForFolio,
  saveProjectBriefForFolio,
  UNTITLED_FOLIO_NAME,
  withFolioTitle,
} from "../../../utils/anti-tabula-rasa";
import {
  loadActiveFolioIdFromIdb,
  loadFolioContentFromIdb,
  loadFoliosFromIdb,
  loadWriterSettingsFromIdb,
  saveActiveFolioIdToIdb,
  saveFolioContentToIdb,
  saveFoliosToIdb,
} from "../../../utils/idb";
import { markDirty } from "../../../utils/convex-sync";
import { captureProductEvent } from "../../../utils/product-analytics";
import { DOSSIER_ROUTE_CLASS } from "../../../utils/conversation-layout";
import {
  waitForDossierFiledFeedback,
  type DossierFilingState,
} from "../../../utils/dossier-filing";

import {
  clearBriefFormDraft,
  moveBriefFormDraft,
} from "../../../utils/brief-form-draft";

interface OnboardingStore {
  hydrated: boolean;
  style: InterviewStyle;
  formAnswers: Partial<ProjectInterviewAnswers> | null;
  formAttachments: DossierAttachment[];
  formProbes: DossierProbe[];
  draftScope: string;
  draftBase: string;
  folioId: string | null;
  folioName: string;
  initialMaterial: string;
}

/**
 * The first-run interview. Renders the AntiTabulaRasa component in `first-run`
 * mode, saves the resulting brief to IndexedDB, seeds a starter document if the
 * writer has nothing yet, and then sends the writer to /editor.
 *
 * The "make an account, or just check things out?" choice and the quick
 * settings live one step earlier in /onboarding; this route is the interview
 * itself. Guests still get a (never forced) sign-up offer once the brief lands.
 */
export default component$(() => {
  const nav = useNavigate();
  const auth = useAuth();
  // Once the brief is saved we offer (but never force) sign-up.
  const briefDone = useSignal(false);
  const filingState = useSignal<DossierFilingState>("idle");
  const store = useStore<OnboardingStore>({
    hydrated: false,
    style: "form",
    formAnswers: null,
    formAttachments: [],
    formProbes: [],
    draftScope: "create:new",
    draftBase: "0",
    folioId: null,
    folioName: "",
    initialMaterial: "",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const [writer, folios, activeFolioId] = await Promise.all([
      loadWriterSettingsFromIdb(),
      loadFoliosFromIdb(),
      loadActiveFolioIdFromIdb(),
    ]);
    store.style = writer.interviewStyle;
    const requestedFolioId = new URLSearchParams(window.location.search).get(
      "folio",
    );
    const folio =
      folios.find((candidate) => candidate.id === requestedFolioId) ??
      folios.find((candidate) => candidate.id === activeFolioId) ??
      null;
    store.folioId = folio?.id ?? null;
    store.draftScope = `create:${store.folioId ?? "new"}`;
    store.folioName = folio?.name ?? "";
    // A folio named in the editor already has a title; start the brief there.
    const folioTitle = briefTitleFromFolioName(store.folioName);
    if (folioTitle) store.formAnswers = { workingTitle: folioTitle };
    const savedBrief = await loadProjectBriefForFolio(store.folioId);
    store.draftBase = String(savedBrief?.updatedAt ?? 0);
    if (savedBrief) {
      store.formAnswers = savedBrief.answers;
      store.formAttachments = savedBrief.attachments;
      store.formProbes = savedBrief.probes ?? [];
      // A cleared brief from Start over intentionally stays in the interview.
      briefDone.value =
        Object.values(savedBrief.answers).some((value) => value.trim()) ||
        savedBrief.attachments.length > 0 ||
        (savedBrief.probes?.length ?? 0) > 0;
    }
    // Pull the manuscript text the refine page stashed when the writer hit
    // "Start over", then clear it so a subsequent ordinary /dossier/create
    // visit doesn't see a stale carry-over.
    store.initialMaterial = loadStartingMaterial();
    clearStartingMaterial();
    store.hydrated = true;
  });

  const completeOnboarding$ = $(
    async (
      answers: ProjectInterviewAnswers,
      existingMaterial?: string,
      filename?: string,
      attachments?: DossierAttachment[],
      probes?: DossierProbe[],
    ) => {
      filingState.value = "filing";
      try {
        answers = withFolioTitle(answers, store.folioName);
        const brief = createProjectBrief(answers, null, attachments, probes);
        let folioId = store.folioId;
        let folioName = store.folioName;
        if (!folioId) {
          const folio: Folio = {
            id: crypto.randomUUID(),
            name: answers.workingTitle || UNTITLED_FOLIO_NAME,
            type: "draft",
            createdAt: Date.now(),
            updatedAt: Date.now(),
          };
          const folios = await loadFoliosFromIdb();
          await saveFoliosToIdb([...folios, folio]);
          await saveActiveFolioIdToIdb(folio.id);
          void captureProductEvent("folio_created", {
            source: "onboarding",
            folio_type: folio.type,
          });
          folioId = folio.id;
          folioName = folio.name;
          store.folioId = folio.id;
          store.folioName = folio.name;
          const scope = `create:${folio.id}`;
          try {
            moveBriefFormDraft(
              sessionStorage,
              store.draftScope,
              scope,
              auth.value.user?.id ?? null,
            );
            store.draftScope = scope;
          } catch {
            /* the open form still holds the full submission */
          }
        }

