export const COMPOSITOR_TABS = [
  {
    id: "home",
    label: "Home",
    groups: ["Character", "Type", "Styles", "Lists", "Alignment"],
  },
  {
    id: "insert",
    label: "Insert",
    groups: ["Objects", "Breaks", "Notes"],
  },
  {
    id: "review",
    label: "Review",
    groups: ["Comments", "Listening", "Versions", "Proofing"],
  },
  {
    id: "view",
    label: "View",
    groups: ["Navigation", "Page", "Help"],
  },
] as const;

export type CompositorTab = (typeof COMPOSITOR_TABS)[number]["id"];

export const DEFAULT_COMPOSITOR_TAB: CompositorTab = "home";

export function isCompositorTab(value: string): value is CompositorTab {
  return COMPOSITOR_TABS.some((tab) => tab.id === value);
}

export function moveCompositorTab(
  current: CompositorTab,
  direction: 1 | -1,
): CompositorTab {
  const currentIndex = COMPOSITOR_TABS.findIndex((tab) => tab.id === current);
  const nextIndex =
    (currentIndex + direction + COMPOSITOR_TABS.length) %
    COMPOSITOR_TABS.length;
  return COMPOSITOR_TABS[nextIndex].id;
}
import type { EditorialBoardTab } from "./editorial-board-overlay";

/**
 * The Editorial Board's tabs, shared by the live editor
 * (`src/routes/editor/index.tsx`) and the landing preview
 * (`src/components/landing/workspace-preview.tsx`).
 *
 * One list so the preview can never silently drop, rename, or reorder a
 * tab the room actually has. Add a tab here and both surfaces follow.
 */
export const BOARD_TABS: EditorialBoardTab[] = [
  {
    id: "personas",
    numeral: "I",
    label: "Cast",
    kicker: "Editors in residence",
    accent: "var(--color-vermilion)",
  },
  {
    id: "rubric",
    numeral: "II",
    label: "Rubric",
    kicker: "Dept. of Rigor",
    accent: "var(--color-ink-light)",
  },
  {
    id: "comments",
    numeral: "III",
    label: "Marginalia",
    kicker: "Notes in the margin",
    accent: "var(--color-mustard)",
  },
  {
    id: "citations",
    numeral: "IV",
    label: "Apparatus",
    kicker: "Sources & sourcerers",
    accent: "var(--color-periwinkle)",
  },
  {
    id: "tools",
    numeral: "V",
    label: "Tools",
    kicker: "Grammar & writing checks",
    accent: "var(--color-vermilion-2)",
  },
  {
    id: "history",
    numeral: "VI",
    label: "Versions",
    kicker: "Version history",
    accent: "var(--color-sage)",
  },
];
import {
  $,
  Slot,
  component$,
  useStore,
  type PropFunction,
} from "@qwik.dev/core";
import { steerBackgroundResearch } from "../../utils/background-research";
import { ChatComposer } from "../ui/chat-composer";
import type { ActivityCounts, PanelId } from "../../utils/panel-activity";

export interface EditorialBoardTab {
  id: PanelId;
  numeral: string;
  label: string;
  kicker: string;
  accent: string;
}

interface EditorialBoardOverlayProps {
  open: boolean;
  activeContext: PanelId;
  activity: ActivityCounts;
  tabs: EditorialBoardTab[];
  onContext$: PropFunction<(panel: PanelId) => void>;
  onClose$: PropFunction<() => void>;
}

interface OverlayStore {
  steeringCollapsed: boolean;
  steeringDraft: string;
  steeringBusy: boolean;
  steeringNotice: string | null;
  steeringError: string | null;
}

/**
 * The Editorial Board as furniture on the manuscript rather than another
 * application rail. Its children remain mounted while closed so searches,
 * streams, replies, and error recovery continue without losing state.
 */
export const EditorialBoardOverlay = component$<EditorialBoardOverlayProps>(
  (props) => {
    const store = useStore<OverlayStore>({
      steeringCollapsed: false,
      steeringDraft: "",
      steeringBusy: false,
      steeringNotice: null,
      steeringError: null,
    });

    const submitSteering = $(async () => {
      const direction = store.steeringDraft.trim();
      if (!direction || store.steeringBusy) return;
      store.steeringBusy = true;
      store.steeringError = null;
      store.steeringNotice = null;
      const result = await steerBackgroundResearch(direction);
      store.steeringBusy = false;
      if (!result.ok) {
        store.steeringError =
          result.message ?? "The Apparatus could not start.";
        return;
      }
      store.steeringNotice = "Direction added to the next research pass.";
      store.steeringDraft = "";
    });

    const activeTab =
      props.tabs.find((tab) => tab.id === props.activeContext) ?? props.tabs[0];

    return (
      <aside
        class={[
          "editorial-overlay",
          {
            "editorial-overlay--apparatus": props.activeContext === "citations",
            "editorial-overlay--closed": !props.open,
          },
        ]}
        aria-label="The Editorial Board"
        aria-hidden={!props.open}
      >
        <div class="editorial-overlay__topline">
          <p class="dept-label">The Editorial Board</p>
          <button
            type="button"
            class="editorial-overlay__close focus-ring"
            onClick$={props.onClose$}
            aria-label="Close the Editorial Board"
          >
            ×
          </button>
        </div>

        <section
          class="editorial-overlay-card editorial-board-card"
          style={{ "--board-accent": activeTab.accent }}
        >
          <header class="editorial-board-card__head">
            <nav class="editorial-board-contexts" aria-label="Board context">
              {props.tabs.map((tab) => {
                const active = tab.id === props.activeContext;
                const unread = props.activity[tab.id] ?? 0;
                return (
                  <button
                    key={tab.id}
                    type="button"
                    class={[
                      "editorial-board-context focus-ring",
                      { "editorial-board-context--active": active },
