): ShortcutPlatform {
  const value = platform.toLocaleLowerCase();
  if (
    value.includes("mac") ||
    value.includes("iphone") ||
    value.includes("ipad")
  ) {
    return "mac";
  }
  if (value.includes("win")) return "windows";
  return "linux";
}

export interface ParsedShortcut {
  modifiers: string[];
  key: string;
