export async function importAs(file: File): Promise<ImportResult> {
  const format = detectFormatFromFilename(file.name);

  if (format === "docx") {
    const mammoth = await import("mammoth/mammoth.browser");
    const result = await mammoth.convertToHtml({
      arrayBuffer: await file.arrayBuffer(),
    });
    const html = result.value;
    const title =
      html
        .match(/<h1[^>]*>(.*?)<\/h1>/i)?.[1]
        ?.replace(/<[^>]+>/g, "")
        .trim() ||
      file.name.replace(/\.docx$/i, "") ||
      "Imported piece";
    return { title, html };
  }

  const text = await file.text();
  if (format === "typst")
    return {
      title: file.name.replace(/\.typ$/i, "") || "Imported piece",
      html: typstToHtml(text),
      typstSource: text,
    };

  if (format === "twyne-backup") {
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch (err) {
      throw new Error(
        `That file doesn't look like a Twyne backup (JSON parse failed: ${(err as Error).message}).`,
      );
    }
    if (
      !parsed ||
      typeof parsed !== "object" ||
      (typeof parsed.content?.html !== "string" &&
        typeof parsed.content?.typstSource !== "string")
    ) {
      throw new Error(
        "That JSON file isn't a Twyne backup. Expected { content: { html }, title, brief }.",
      );
    }
    return {
      title: parsed.title ?? "Imported piece",
      html:
        typeof parsed.content.typstSource === "string"
          ? typstToHtml(parsed.content.typstSource)
          : parsed.content.html,
      typstSource:
        typeof parsed.content.typstSource === "string"
          ? parsed.content.typstSource
          : undefined,
      brief: parsed.brief ?? null,
      folios: parsed.folios ?? undefined,
    };
  }

  if (format === "html") {
    return parseHtmlImport(text, file.name);
  }

  if (format === "txt") {
    const escaped = escapeHtml(text);
    const html = escaped
      .split(/\n{2,}/)
      .map((p) => `<p>${p.replace(/\n/g, "<br />")}</p>`)
      .join("\n");
    const title = firstLine(text) || "Imported piece";
    return { title, html };
  }

  // markdown
  marked.setOptions({ async: false, breaks: true, gfm: true });
  const html = marked.parse(text) as string;
  const title = firstLine(text) || "Imported piece";
  return { title, html };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function firstLine(text: string): string | null {
  const m = text.match(/^#\s+(.+)$/m);
  if (m) return m[1].trim();
  const first = text.split(/\n/).find((l) => l.trim());
  return first ? first.trim() : null;
}

